export type RewardsSummary={universalPoints:number;pendingPoints:number;cashbackCents:number;tier:string};
export interface RewardsGateway{getSummary(userId:string):Promise<RewardsSummary>;setCashbackDestination(userId:string,destination:'wallet'|'main'|`pot:${string}`):Promise<void>;redeem(input:{userId:string;points:number;merchantId?:string;paymentReference?:string}):Promise<{redemptionId:string;valueCents:number}>}
export class MockRewardsGateway implements RewardsGateway{private state=new Map<string,RewardsSummary>();async getSummary(id:string){return this.state.get(id)||{universalPoints:4850,pendingPoints:620,cashbackCents:1840,tier:'gold'}}async setCashbackDestination(){return}async redeem({userId,points}:{userId:string;points:number}){const s=await this.getSummary(userId);if(points>s.universalPoints)throw new Error('insufficient_points');s.universalPoints-=points;this.state.set(userId,s);return{redemptionId:crypto.randomUUID(),valueCents:points}}}
